// Aus dem OPC-UA-Wert ein einheitliches JSON-Objekt machen.
// Dieses Objekt geht an WebSocket, MQTT und Datenbank.

// Beim Start eines Abonnements meldet der OPC-UA-Client einmal seine
// Abonnement-Nummer (topic "subscriptionId"). Das ist kein Messwert.
if (msg.topic === "subscriptionId") return null;

const value = Number(msg.payload);
if (!Number.isFinite(value)) {
    node.warn("Kein Zahlenwert erhalten: " + msg.payload);
    return null;
}
const zeit = msg.sourceTimestamp ? new Date(msg.sourceTimestamp) : new Date();

msg.payload = {
    source: "P-101 Vibration",
    nodeId: msg.topic,
    value: Math.round(value * 1000) / 1000,
    unit: "mm/s",
    timestamp: zeit.toISOString(),
    // Alarmgrenzen laut OPC-UA-Server (VibrationAlarm: HighLimit / HighHighLimit)
    limits: { high: 4.5, highHigh: 7.1 }
};
node.status({ fill: "green", shape: "dot", text: msg.payload.value + " mm/s" });
return msg;

// Jeden Messwert in die Tabelle "vibration" schreiben
const db = flow.get("p101db");
if (!db) {
    node.error("Datenbank ist nicht geöffnet", msg);
    return null;
}
const ts = Date.parse(msg.payload.timestamp) || Date.now();
db.prepare("INSERT INTO vibration (ts, value) VALUES (?, ?)").run(ts, msg.payload.value);

// Alle 10 Minuten Werte löschen, die älter als 24 Stunden sind (schont die SD-Karte)
let zaehler = (context.get("zaehler") || 0) + 1;
if (zaehler >= 600) {
    db.prepare("DELETE FROM vibration WHERE ts < ?").run(Date.now() - 24 * 60 * 60 * 1000);
    zaehler = 0;
}
context.set("zaehler", zaehler);

const anzahl = db.prepare("SELECT COUNT(*) AS n FROM vibration").get().n;
node.status({ fill: "green", shape: "dot", text: anzahl + " Werte gespeichert" });
return null;

initialize:
// SQLite ist in Node.js 22 eingebaut (node:sqlite), es muss nichts kompiliert werden.
// Node-RED erkennt "node:sqlite" im Setup-Tab nicht als eingebautes Modul,
// darum wird es über createRequire aus dem eingebauten Modul "module" geladen.
const requireBuiltin = moduleLib.createRequire(path.join(os.homedir(), "/"));
const { DatabaseSync } = requireBuiltin("node:sqlite");

// Datenbankdatei: ~/.node-red/p101.db (oder Umgebungsvariable P101_DB)
const datei = env.get("P101_DB") || path.join(os.homedir(), ".node-red", "p101.db");
fs.mkdirSync(path.dirname(datei), { recursive: true });

const db = new DatabaseSync(datei);
db.exec(`
    PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS vibration (
        ts    INTEGER NOT NULL,  -- Zeitpunkt in ms seit 1970 (UTC)
        value REAL    NOT NULL   -- Vibration in mm/s
    );
    CREATE INDEX IF NOT EXISTS idx_vibration_ts ON vibration (ts);
`);

// Die Verbindung im Flow-Kontext ablegen, damit der REST-Endpunkt sie mitbenutzt
flow.set("p101db", db);
node.status({ fill: "grey", shape: "ring", text: "bereit: " + path.basename(datei) });

finalize:
// Beim Neu-Deployen oder Stoppen die Datenbank sauber schließen
const db = flow.get("p101db");
if (db) {
    db.close();
    flow.set("p101db", undefined);
}

func:
// GET /api/p101/vibration?minutes=5
// Liefert die Messwerte der letzten Minuten (Standard 5, höchstens 60) als JSON.
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",   // Webapp auf GitHub Pages darf abfragen
    "Cache-Control": "no-store"
};

const db = flow.get("p101db");
if (!db) {
    msg.statusCode = 503;
    msg.payload = { error: "Datenbank nicht bereit" };
    return msg;
}

let minutes = parseInt(msg.req.query.minutes, 10);
if (!Number.isFinite(minutes)) minutes = 5;
minutes = Math.min(Math.max(minutes, 1), 60);

const seit = Date.now() - minutes * 60 * 1000;
const rows = db.prepare("SELECT ts, value FROM vibration WHERE ts >= ? ORDER BY ts").all(seit);

msg.statusCode = 200;
msg.payload = {
    source: "P-101 Vibration",
    unit: "mm/s",
    minutes: minutes,
    count: rows.length,
    data: rows.map(r => ({ timestamp: new Date(r.ts).toISOString(), value: r.value }))
};
return msg;
